//! Purpose:
//! Generated Rust tests for the committed PHP 8.5.10 `ext/tidy` PHPT corpus.
//!
//! Called from:
//! - `cargo test` through `tests/codegen/tidy_php_src.rs`.
//!
//! Key details:
//! - Generated by `scripts/gen_php_src_tidy_cases.py`; do not hand-edit.
//! - Each test carries its PHP source and assertion inline, and the test process
//!   never parses a `.phpt` file at run time.
//! - Fixtures php-src skips on this platform, and the one known elephc divergence,
//!   are preserved as ignored cases with the original reason.

#![allow(non_snake_case)]

#[allow(unused_imports)]
use super::{assert_bytes, assert_format, assert_regex, run_case, skip_without_tidy_native};

/// Replays php-src `001.phpt`.
#[test]
fn test_php_src_tidy_001() {
    if skip_without_tidy_native("test_php_src_tidy_001") { return; }
    let out = run_case("<?php\n\necho \"tidy extension is available\";\n", "", &[], &[], false);
    assert_bytes(&out, b"tidy extension is available");
}

/// Replays php-src `002.phpt`.
#[test]
fn test_php_src_tidy_002() {
    if skip_without_tidy_native("test_php_src_tidy_002") { return; }
    let out = run_case("<?php\n\n        $a = tidy_parse_string(\"<HTML></HTML>\");\n        echo tidy_get_output($a);\n\n", "", &[], &[], false);
    assert_bytes(&out, b"<html>\n<head>\n<title></title>\n</head>\n<body>\n</body>\n</html>");
}

