/// Replays php-src `004.phpt`.
#[test]
fn test_php_src_tidy_004() {
    if skip_without_tidy_native("test_php_src_tidy_004") { return; }
    let out = run_case("<?php\n\n$a = tidy_parse_string('<HTML></HTML>');\nvar_dump(tidy_diagnose($a));\necho str_replace(\"\\r\", \"\", tidy_get_error_buffer($a));\n\n$html = <<< HTML\n<!DOCTYPE html PUBLIC \"-//W3C//DTD HTML 3.2//EN\">\n<html>\n<head><title>foo</title></head>\n<body><p>hello</p></body>\n</html>\nHTML;\n$a = tidy_parse_string($html);\nvar_dump(tidy_diagnose($a));\necho tidy_get_error_buffer($a);\n", "", &[], &[], false);
    assert_format(&out, b"bool(true)\nline 1 column 1 - Warning: missing <!DOCTYPE> declaration\nline 1 column 7 - Warning: discarding unexpected </html>\nline 1 column 14 - Warning: inserting missing 'title' element\nInfo: Document content looks like HTML%w%d%S\n%S3 warnings%S0 errors%S\nbool(true)\nInfo: Document content looks like HTML 3.2\nNo warnings or errors were found.");
}

