/// Replays php-src `007.phpt`.
#[test]
fn test_php_src_tidy_007() {
    if skip_without_tidy_native("test_php_src_tidy_007") { return; }
    let out = run_case("<?php\n\n$a = new tidy(__DIR__.\"/007.html\");\necho \"Current Value of 'tidy-mark': \";\nvar_dump($a->getopt(\"tidy-mark\"));\necho \"Current Value of 'error-file': \";\nvar_dump($a->getopt(\"error-file\"));\necho \"Current Value of 'tab-size': \";\nvar_dump($a->getopt(\"tab-size\"));\n\ntry {\n    $a->getopt('bogus-opt');\n} catch (ValueError $exception) {\n    echo $exception->getMessage() . \"\\n\";\n}\n\ntry {\n    tidy_getopt($a, 'non-ASCII string ���');\n} catch (ValueError $exception) {\n    echo $exception->getMessage() . \"\\n\";\n}\n\n", "", &[(r#"tidy.default_config"#, r#""#)], &[], false);
    assert_bytes(&out, b"Current Value of 'tidy-mark': bool(false)\nCurrent Value of 'error-file': string(0) \"\"\nCurrent Value of 'tab-size': int(8)\ntidy::getOpt(): Argument #1 ($option) is an invalid configuration option, \"bogus-opt\" given\ntidy_getopt(): Argument #2 ($option) is an invalid configuration option, \"non-ASCII string \xef\xbf\xbd\xef\xbf\xbd\xef\xbf\xbd\" given");
}

