/// Replays php-src `011.phpt`.
#[test]
fn test_php_src_tidy_011() {
    if skip_without_tidy_native("test_php_src_tidy_011") { return; }
    let out = run_case("<?php\n\n        $a = tidy_parse_string(\"<HTML><BODY BGCOLOR=#FFFFFF ALINK=#000000></BODY></HTML>\");\n        $body = $a->body();\n        var_dump($body->attribute);\n        foreach($body->attribute as $key=>$val) {\n            echo \"Attrib '$key': $val\\n\";\n        }\n", "", &[], &[], false);
    assert_bytes(&out, b"array(2) {\n  [\"bgcolor\"]=>\n  string(7) \"#FFFFFF\"\n  [\"alink\"]=>\n  string(7) \"#000000\"\n}\nAttrib 'bgcolor': #FFFFFF\nAttrib 'alink': #000000");
}

