/// Replays php-src `027.phpt`.
#[test]
fn test_php_src_tidy_027() {
    if skip_without_tidy_native("test_php_src_tidy_027") { return; }
    let out = run_case("<?php\n\n\n// bug report from http://sf.net/tracker/?func=detail&atid=390963&aid=1641868&group_id=27659\n\nabstract class BaseClass {\n        private static $tidyconfig;\n\n        public function __construct() {\n                self::$tidyconfig = array(\n                        'indent'                        => false,\n                        'clean'                         => true,\n                        'merge-divs'            => false,\n                        'quote-marks'           => true,\n                        'drop-empty-paras'      => false,\n                        'markup'                        => false,\n                        'output-xhtml'          => true,\n                        'wrap'                          => 0);\n\n        }\n\n        abstract public function run();\n\n        public function getURL($url) {\n                $data = \"awerawer\"; // in my code, $data is downloaded from a site\n\n                $tidy = new tidy;\n                $tidy->parseString($data, self::$tidyconfig, 'utf8');\n                $tidy->cleanRepair();\n\n                return $tidy;\n        }\n\n}\n\nclass ChildClass extends BaseClass {\n        public function __construct() {\n                parent::__construct();\n        }\n\n        public function run() {\n                $result = $this->getURL('awer');\n                if ($result === null) {\n                        echo \"\\tError:\\n\";\n                }\n                var_dump((string)$result);\n        }\n}\n\n$instance = new ChildClass();\n$instance->run();\n\n", "", &[], &[], false);
    assert_bytes(&out, b"string(0) \"\"");
}

