/// Replays php-src `gh20374.phpt`.
#[test]
fn test_php_src_tidy_gh20374() {
    if skip_without_tidy_native("test_php_src_tidy_gh20374") { return; }
    let out = run_case("<?php\n\n\nclass MyStringable {\n\tpublic function __construct(private $ret) {}\n\n\tpublic function __toString(): string {\n\t\treturn $this->ret;\n\t}\n}\n\nclass MyThrowingStringable {\n    public function __toString(): string {\n        throw new Error('no');\n    }\n}\n\n$values = [\n\t'string blocklevel' => 'blocklevel',\n\t'int' => 1,\n\t'double overflow' => (string) (2.0**80.0),\n\t'numeric string int 1' => '1',\n\t'numeric string double 1.0' => '1.0',\n\t'false' => false,\n\t'true' => true,\n\t'NAN' => NAN,\n\t'INF' => INF,\n\t'object with numeric string int 0' => new MyStringable('0'),\n\t'object with string blocklevel' => new MyStringable('blocklevel'),\n    'object with string empty' => new MyStringable('empty'),\n    'object with exception' => new MyThrowingStringable,\n];\n\nforeach ($values as $key => $value) {\n\techo \"--- $key ---\\n\";\n\t$str = '<custom-html-element>test</custom-html-element>';\n\n\t$config = [\n\t\t'custom-tags' => $value,\n\t];\n\n\t$tidy = new tidy();\n    try {\n        $tidy->parseString($str, $config, 'utf8');\n        echo $tidy->value, \"\\n\";\n    } catch (Throwable $e) {\n        echo $e::class, \": \", $e->getMessage(), \"\\n\";\n    }\n}\n\n", "", &[], &[], false);
    assert_format(&out, b"--- string blocklevel ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\n<custom-html-element>test</custom-html-element>\n</body>\n</html>\n--- int ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\n<custom-html-element>test</custom-html-element>\n</body>\n</html>\n--- double overflow ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\ntest\n</body>\n</html>\n--- numeric string int 1 ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\n<custom-html-element>test</custom-html-element>\n</body>\n</html>\n--- numeric string double 1.0 ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\n<custom-html-element>test</custom-html-element>\n</body>\n</html>\n--- false ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\ntest\n</body>\n</html>\n--- true ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\n<custom-html-element>test</custom-html-element>\n</body>\n</html>\n--- NAN ---\n\nWarning: The float NAN is not representable as an int, cast occurred in %s on line %d\n<html>\n<head>\n<title></title>\n</head>\n<body>\ntest\n</body>\n</html>\n--- INF ---\n\nWarning: The float INF is not representable as an int, cast occurred in %s on line %d\n<html>\n<head>\n<title></title>\n</head>\n<body>\ntest\n</body>\n</html>\n--- object with numeric string int 0 ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\ntest\n</body>\n</html>\n--- object with string blocklevel ---\n<html>\n<head>\n<title></title>\n</head>\n<body>\n<custom-html-element>test</custom-html-element>\n</body>\n</html>\n--- object with string empty ---\n<custom-html-element>\n<html>\n<head>\n<title></title>\n</head>\n<body>\ntest\n</body>\n</html>\n--- object with exception ---\nError: no");
}

/// Replays php-src `open_basedir_failure_config.phpt`.
#[test]
fn test_php_src_tidy_open_basedir_failure_config() {
    if skip_without_tidy_native("test_php_src_tidy_open_basedir_failure_config") { return; }
    let out = run_case("<?php\n\necho \"=== repairString ===\\n\";\n$tidy = new tidy;\n$tidy->repairString('my epic string', 'my_config_file.ini');\n\necho \"=== tidy_parse_string ===\\n\";\ntidy_parse_string('my epic string', 'my_config_file.ini');\n\necho \"=== tidy_parse_file ===\\n\";\ntidy_parse_file(__DIR__.'/open_basedir/test.html', 'my_config_file.ini');\n\necho \"=== __construct ===\\n\";\ntry {\n    $tidy = new tidy(__DIR__.'/open_basedir/test.html', 'my_config_file.ini');\n} catch (Exception $e) {\n    echo $e->getMessage(), \"\\n\";\n}\n\necho \"=== parseFile ===\\n\";\n$tidy = new tidy;\n$tidy->parseFile(__DIR__.'/open_basedir/test.html', 'my_config_file.ini');\n\necho \"=== parseString ===\\n\";\n$tidy = new tidy;\n$tidy->parseString('my epic string', 'my_config_file.ini');\n", "", &[(r#"open_basedir"#, r#"{PWD}/open_basedir"#)], &[], false);
    assert_format(&out, b"=== repairString ===\n\nWarning: tidy::repairString(): open_basedir restriction in effect. File(my_config_file.ini) is not within the allowed path(s): (%sopen_basedir) in %s on line %d\n=== tidy_parse_string ===\n\nWarning: tidy_parse_string(): open_basedir restriction in effect. File(my_config_file.ini) is not within the allowed path(s): (%sopen_basedir) in %s on line %d\n=== tidy_parse_file ===\n\nWarning: tidy_parse_file(): open_basedir restriction in effect. File(my_config_file.ini) is not within the allowed path(s): (%sopen_basedir) in %s on line %d\n=== __construct ===\ntidy::__construct(): open_basedir restriction in effect. File(my_config_file.ini) is not within the allowed path(s): (%sopen_basedir)\n=== parseFile ===\n\nWarning: tidy::parseFile(): open_basedir restriction in effect. File(my_config_file.ini) is not within the allowed path(s): (%sopen_basedir) in %s on line %d\n=== parseString ===\n\nWarning: tidy::parseString(): open_basedir restriction in effect. File(my_config_file.ini) is not within the allowed path(s): (%sopen_basedir) in %s on line %d");
}

/// Replays php-src `parsing_file_too_large.phpt`.
#[test]
    #[ignore = "php-src SKIP on this platform: RUN_RESOURCE_HEAVY_TESTS/GITHUB_ACTIONS guard; writes a multi-gigabyte fixture"]
fn test_php_src_tidy_parsing_file_too_large() {
    if skip_without_tidy_native("test_php_src_tidy_parsing_file_too_large") { return; }
    let out = run_case("<?php\n\n\n$path = __DIR__ . '/too_large_test.html';\n$file = fopen($path, 'w+');\n\n// Write over 4GB\nconst MIN_FILE_SIZE = 4_294_967_295;\n\nvar_dump(fseek($file, MIN_FILE_SIZE+10));\n$s = str_repeat(\"a\", 10);\n$bytes_written = fwrite($file, $s);\nif ($bytes_written === false) {\n    echo \"Didn't write bytes\\n\";\n}\n\n$tidy = new tidy;\ntry {\n    var_dump($tidy->parseFile($path));\n} catch (\\Throwable $e) {\n    echo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\n\ntry {\n    var_dump(tidy_parse_file($path));\n} catch (\\Throwable $e) {\n    echo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\n\ntry {\n    $tidy = new tidy($path);\n} catch (\\Throwable $e) {\n    echo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\n\ntry {\n    tidy_repair_file($path);\n} catch (\\Throwable $e) {\n    echo $e::class, ': ', $e->getMessage(), PHP_EOL;\n}\n", "", &[(r#"memory_limit"#, r#""5G""#)], &[], false);
    assert_bytes(&out, b"int(0)\nValueError: File content is too long\nValueError: File content is too long\nValueError: File content is too long\nValueError: tidy_repair_file(): Argument #1 ($filename) File content is too long");
}

