/// Replays php-src `tidy_error1.phpt`.
#[test]
fn test_php_src_tidy_tidy_error1() {
    if skip_without_tidy_native("test_php_src_tidy_tidy_error1") { return; }
    let out = run_case("<?php\n\n$buffer = '<html></html>';\n$config = ['bogus' => 'willnotwork'];\n\n$tidy = new tidy();\n\ntry {\n\t$tidy->parseString($buffer, $config);\n} catch (\\ValueError $e) {\n\techo $e::class, \": \", $e->getMessage(), PHP_EOL;\n}\n\n$config = ['neither'];\ntry {\n\t$tidy->parseString($buffer, $config);\n} catch (\\TypeError $e) {\n\techo $e::class, \": \", $e->getMessage(), PHP_EOL;\n}\n\n$config = ['doctype-mode' => 'customtag'];\n\ntry {\n\tvar_dump($tidy->parseString($buffer, $config));\n} catch (\\ValueError $e) {\n\techo $e::class, \": \", $e->getMessage(), PHP_EOL;\n}\n\n$config = ['doctype' => 'php'];\n\ntry {\n\tvar_dump($tidy->parseString($buffer, $config));\n} catch (\\TypeError $e) {\n\techo $e::class, \": \", $e->getMessage(), PHP_EOL;\n}\n\n$config = ['doctype' => 'auto', 0 => 'value2'];\n\ntry {\n\tvar_dump($tidy->parseString($buffer, $config));\n} catch (\\TypeError $e) {\n\techo $e::class, \": \", $e->getMessage(), PHP_EOL;\n}\n\n", "", &[], &[], false);
    assert_bytes(&out, b"ValueError: tidy::parseString(): Argument #2 ($config) Unknown Tidy configuration option \"bogus\"\nTypeError: tidy::parseString(): Argument #2 ($config) must be of type array with keys as string\nValueError: tidy::parseString(): Argument #2 ($config) Attempting to set read-only option \"doctype-mode\"\nTypeError: tidy::parseString(): Argument #2 ($config) option \"doctype\" does not accept \"php\" as a value\nTypeError: tidy::parseString(): Argument #2 ($config) must be of type array with keys as string");
}

